namespace UngaBunga45001{
 public sealed class TemperateHydroAuditV19:MonoBehaviour{
 [Serializable]class Check{public string name,detail;public bool passed;}
 [Serializable]class Report{public string status,scope="Prepared fresh-save river fixture. Physical CharacterController entry/exit, live water depth, footstep rings and native-actor grass shader inputs. Keyboard/touch controls are verified separately.";public Check[] checks;public string[] errors;}
 const string Out="E:/UNGA-BUNGA-45001/Revision19/Environment/";readonly List<Check> checks=new List<Check>();readonly List<string> errors=new List<string>();CampaignRuntime c;ThirdPersonMotor motor;CharacterController body;bool complete;
 void Write()=>File.WriteAllText(Out+"hydro-validation.json",JsonUtility.ToJson(new Report{status=checks.Any(x=>!x.passed)||errors.Count>0?"failed":complete?"passed":"running",checks=checks.ToArray(),errors=errors.ToArray()},true));
