 IEnumerator Walk(Vector3 target,float seconds){float end=Time.time+seconds;while(Time.time<end){var d=target-c.bindings.player.position;d.y=0;if(d.magnitude<.14f)yield break;body.Move((d.normalized*(motor.walkSpeed*(c.GetComponent<EnvironmentInteraction>().WaterDepth>.08f?.55f:1))+Vector3.down*2)*Time.deltaTime);motor.visual.rotation=Quaternion.LookRotation(d);VillageLife.Play(c.bindings.AnimatorFor("dylan"),"Locomotion");c.bindings.AnimatorFor("dylan").SetFloat("Speed",.4f);yield return null;}}
 IEnumerator Start(){if(!TribalInterfaceAudit.Requested)throw new Exception("Isolated save required");Application.logMessageReceived+=Log;c=GetComponent<CampaignRuntime>();yield return new WaitUntil(()=>c.State!=null);c.GetComponent<CinematicTriggersV15>().SuspendAutomatic=true;c.cinematicDirector.Skip();yield return new WaitUntil(()=>!c.cinematicDirector.IsPlaying);c.NewCampaign();yield return null;c.cinematicDirector.Skip();yield return new WaitUntil(()=>!c.cinematicDirector.IsPlaying);c.State.pendingCinematicsV15.Clear();c.SetPause(false);yield return new WaitForSeconds(3);motor=c.bindings.player.GetComponent<ThirdPersonMotor>();motor.enabled=false;body=c.bindings.player.GetComponent<CharacterController>();var water=c.GetComponent<EnvironmentInteraction>();var river=water.webWaterPlanes.FirstOrDefault(x=>x.renderer!=null&&x.renderer.name.Contains("Rivière"));CheckThat("new river participates in water queries",river!=null);if(river==null){complete=true;Write();Destroy(this);yield break;}float z=270,x=286.5f+Mathf.Sin((z-245)*.058f)*2.8f;var center=new Vector3(x,0,z);center.y=VillageLife.Ground(center);var bank=center+Vector3.right*4.5f;bank.y=VillageLife.Ground(bank);water.SampleDepth(center,out float deep);water.SampleDepth(bank,out float dry);CheckThat("channel is deeper than the maintained bank",deep>.45f&&dry<.08f,$"channel={deep:0.000}; bank={dry:0.000}");Place(bank);yield return null;int before=water.SplashEmissions;yield return Walk(center,20);yield return new WaitForSeconds(.3f);CheckThat("physical body enters the water",water.WaterDepth>.5f&&Vector3.Distance(c.bindings.player.position,bank)>3,water.WaterDepth.ToString("0.000"));CheckThat("moving feet create real water rings",water.SplashEmissions>before,(water.SplashEmissions-before).ToString());int actors=Shader.GetGlobalInt("_UngaActorCount");var positions=Shader.GetGlobalVectorArray("_UngaActors");bool playerInGrass=positions.Take(actors).Any(p=>Vector3.Distance(new Vector3(p.x,p.y,p.z),c.bindings.player.position)<.2f);CheckThat("native player feeds the grass interaction shader",actors>0&&playerInGrass,actors.ToString());TemperateEnvironmentAuditV19.Capture(c.bindings.gameplayCamera,center+new Vector3(5,3,-6),center+Vector3.up*.6f,Out+"Review/K-riviere.png");yield return Walk(bank,20);yield return new WaitForSeconds(.3f);CheckThat("body returns to the dry grounded bank",water.WaterDepth<.08f&&Mathf.Abs(c.bindings.player.position.y-VillageLife.Ground(c.bindings.player.position))<.12f,water.WaterDepth.ToString("0.000"));complete=true;Write();motor.enabled=true;Application.logMessageReceived-=Log;Destroy(this);}
 void OnDestroy(){if(motor!=null)motor.enabled=true;Application.logMessageReceived-=Log;}
 }
